add_action( 'woocommerce_after_checkout_form', 'perfectpixel_toggle_field_by_another' );

function perfectpixel_toggle_field_by_another() {
	$source = 'billing_company'; // Field that is watched.
	$target = 'billing_phone';   // Field shown only when $source is not empty.
	?>
	<script>
	( function () {
		var source = document.getElementById( <?php echo wp_json_encode( $source ); ?> );
		var row = document.getElementById( <?php echo wp_json_encode( $target . '_field' ); ?> );
		if ( ! source || ! row ) {
			return;
		}
		var update = function () {
			row.style.display = source.value.trim() ? '' : 'none';
		};
		source.addEventListener( 'input', update );
		update();
	} )();
	</script>
	<?php
}
